/**
 * QR asset registry — the ONE source for "which URL renders this QR payload".
 *
 * WHY THIS EXISTS
 * ---------------
 * A QR layer's `payload` is the business slug the code must point at, and the
 * device QR is generated by our own API (`/public/businesses/{slug}/qr`). The
 * renderer and the SVG/PDF exporter used to hit the public same-origin proxy
 * (`/api/qr/{slug}`) with a plain `<img>`/`fetch` — no Authorization header.
 * That is exactly right for an APPROVED business (its QR is public and the
 * proxy caches it hard) and exactly wrong for a DRAFT one: the API answers 404
 * to anonymous callers, so the newly added QR of a not-yet-approved business
 * showed the empty placeholder forever, in the editor and in the export.
 *
 * The fix keeps the public path untouched and adds an OWNER-SESSION override:
 * while the studio is open it fetches the QR through the authenticated API
 * client and registers the resulting data URL here; the renderer and the
 * exporter consult this registry FIRST. Public pages never register anything,
 * so they behave exactly as before (same-origin proxy, cacheable, no token).
 *
 * Pure module state (no React, no DOM) so both the React renderer and the
 * non-React exporter can read it.
 */

/** Data URL (or same-origin URL) per QR payload (business slug). */
const registered = new Map<string, string>();

/** Normalize a QR payload into the slug it must resolve to. */
export function qrSlug(payload: string | null | undefined): string {
  return (payload ?? "").trim();
}

/**
 * The URL that renders this payload: the authenticated override when the
 * current session registered one, otherwise the public same-origin proxy.
 * Returns null for an empty payload (the renderer shows its honest placeholder).
 */
export function qrSrcFor(payload: string | null | undefined): string | null {
  const slug = qrSlug(payload);
  if (!slug) return null;
  return registered.get(slug) ?? `/api/qr/${encodeURIComponent(slug)}`;
}

/** The authenticated data URL registered for this payload, if any. */
export function registeredQrSrc(payload: string | null | undefined): string | undefined {
  const slug = qrSlug(payload);
  return slug ? registered.get(slug) : undefined;
}

/** Register an owner-session QR (data URL). Empty values are ignored. */
export function registerQrAsset(payload: string, url: string | null | undefined): void {
  const slug = qrSlug(payload);
  if (!slug || !url) return;
  registered.set(slug, url);
}

/** Forget every registered asset (tests + logout hygiene). */
export function clearQrAssets(): void {
  registered.clear();
}
